export function translatePhrase(text: string, language: SiteLanguage): string {
  if (language === "en") return text;
  const trimmed = text.trim();
  const translated = phrases[trimmed] ?? legalGuideTranslations[trimmed] ??
    Object.entries(phrases).find(([k]) => k.trim().toLowerCase() === trimmed.toLowerCase())?.[1] ??
    Object.entries(legalGuideTranslations).find(([k]) => k.trim().toLowerCase() === trimmed.toLowerCase())?.[1];
  return translated ? translated[language === "hi" ? 0 : 1] : text;
}
